function digitSum(n){ var s=0; n=Math.abs(Math.floor(n)); while(n>0){ s+=n%10; n=Math.floor(n/10);} return s; }
function digitalRoot(n){
  n=Math.floor(Math.abs(+n));
  if(isNaN(n)) return {error:'请输入非负整数'};
  if(n===0) return {value:0, root:0, steps:0, origin:0};
  var steps=0, cur=n;
  while(cur>=10){ cur=digitSum(cur); steps++; }
  return {value:cur, root:cur, steps:steps, origin:n};
}
var EXPORTS={digitalRoot:digitalRoot};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.DigitalRootForgePure = EXPORTS; }
